+/**
+ * Check if user has access to populate specific fields
+ * @param {Object} populate - The populate query object
+ * @param {Object} user - The authenticated user
+ * @param {Object} model - The content type model
+ * @param {Object} strapi - Strapi instance
+ * @returns {Promise<Boolean>}
+ */
+async function checkFieldAccess(populate, user, model, strapi) {
+  if (!populate || !user) {
+    return false;
+  }
+
+  // Get user's role and permissions
+  const userRole = user.role;
+  if (!userRole) {
+    return false;
+  }
+
+  // Recursively check all fields in populate query
