+  for (const field of fieldsToCheck) {
+    const fieldName = typeof field === 'string' ? field : field.path;
+    
+    if (!fieldName) {
+      continue;
+    }
+
+    // Check if user has permission to populate this field
+    const hasPermission = await strapi
+      .plugin('users-permissions')
+      .service('userspermissions')
+      .getFieldPermission(model.uid, fieldName, userRole.id);
+
+    if (!hasPermission) {
+      return false;
+    }
+  }
+
+  return true;
+}
+
+module.exports = { checkFieldAccess };

